31	    handle = await open(path, 'r');
32	  } catch (err) {
33	    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') throw new InputError('no such file', 1);
34	    if (await isDirectory(path)) throw new InputError('is a directory', 1);
35	    throw new InputError('cannot read', 1);
36	  }
