import { pathToFileURL } from 'node:url';
import { isDeepStrictEqual } from 'node:util';
const dir = process.argv[2];
const m = await import(pathToFileURL(`${dir}/jsonpatch.mjs`).href);
const { parsePointer, applyPatch, PatchError } = m;
let fails = 0;
function chk(name, got, exp) {
  if (!isDeepStrictEqual(got, exp)) { fails++; console.log('FAIL', name, JSON.stringify(got), 'expected', JSON.stringify(exp)); }
}
function run(doc, patch) {
  try { const r = applyPatch(doc, patch); return { ok: r }; }
  catch (e) { return { err: e instanceof PatchError && e instanceof Error ? `${e.name}|${e.message}|${e.index}` : `OTHER ${e?.constructor?.name} ${e?.message}` }; }
}
function pp(p) { try { return parsePointer(p); } catch (e) { return `${e.constructor.name}:${e.message}`; } }

